INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47461, 'Exodus 18:25', 'Exodus', 18, 25, 'او د ټولو اسراییلیانو څخه یې لایقه کسان وټاکل. هغوی یې په زر کسیزه، سل کسیزه، پنځوس کسیزه او لس کسیزه ډلو باندې مشران وټاکل.', 'او د تولو اسراییلیانو چخه یې لایقه کسان وتاکل. هغوی یې په زر کسیزه، سل کسیزه، پنجوس کسیزه او لس کسیزه دلو باندې مشران وتاکل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_18_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47462, 'Exodus 18:26', 'Exodus', 18, 26, 'هغوی به تل د قاضیانو په توګه د خلکو خدمت کاوه. هغوی به سختې دعوې موسی ته راوړلې، خو د ساده دعوو پرېکړه به یې په خپله کوله.', 'هغوی به تل د قاضیانو په توګه د خلکو خدمت کاوه. هغوی به سختې دعوې موسی ته راورلې، خو د ساده دعوو پرېکره به یې په خپله کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_18_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47463, 'Exodus 18:27', 'Exodus', 18, 27, 'بیا موسی خپل خسر یترون رخصت کړ او یترون خپل وطن ته ستون شو.', 'بیا موسی خپل خسر یترون رخصت کر او یترون خپل وطن ته ستون شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_18_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47464, 'Psalms 26:1', 'Psalms', 26, 1, 'ته ښکاره کړه ای څښتنه چې زه یمه بې‌ګناه دې دپاره چې کومه سم کارونه او په تا باندې توکل کومه بې له شکه', 'ته شکاره کره ای چشتنه چې زه یمه بې‌ګناه دې دپاره چې کومه سم کارونه او په تا باندې توکل کومه بې له شکه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47465, 'Psalms 26:2', 'Psalms', 26, 2, 'کړه امتحان مې ای څښتنه او مې وازمایلو زما د زړه او ذهن دواړو ازمېښت وکړه ته', 'کره امتحان مې ای چشتنه او مې وازمایلو زما د زره او ذهن دوارو ازمېشت وکره ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47466, 'Psalms 26:3', 'Psalms', 26, 3, 'ځکه ستا تلپاتې مینه زما په سترګو کې ده زه تېرومه خپل ژوند ستا وفادارۍ کې', 'جکه ستا تلپاتې مینه زما په سترګو کې ده زه تېرومه خپل ژوند ستا وفاداری کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47467, 'Psalms 26:4', 'Psalms', 26, 4, 'د دروغجنو خلکو ملګرتیا نه کوم د منافقو هېڅ ملتیا نه کوم', 'د دروغجنو خلکو ملګرتیا نه کوم د منافقو هېچ ملتیا نه کوم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47468, 'Psalms 26:5', 'Psalms', 26, 5, 'زه د بدانو د ناستې نه نفرت کومه او د بدکارانو سره نه کښېنمه', 'زه د بدانو د ناستې نه نفرت کومه او د بدکارانو سره نه کشېنمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47469, 'Psalms 26:6', 'Psalms', 26, 6, 'خپل لاسونه زه وینځمه چې دا وښایم بې‌ګناه یم قربانګاه نه دې تاوېږم ای څښتنه', 'خپل لاسونه زه وینجمه چې دا وشایم بې‌ګناه یم قربانګاه نه دې تاوېزم ای چشتنه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47470, 'Psalms 26:7', 'Psalms', 26, 7, 'په لوړ اواز وایم سندرې او ادا کوم ستا شکر بیانومه زه ستا ټول عجیبه کارونه', 'په لور اواز وایم سندرې او ادا کوم ستا شکر بیانومه زه ستا تول عجیبه کارونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47471, 'Psalms 26:8', 'Psalms', 26, 8, 'ای څښتنه، هغه کور کې چې ته اوسې په ما ګران دی هغه ځای کې چې جلال د ستا اوسیږي په ما ګران دی', 'ای چشتنه، هغه کور کې چې ته اوسې په ما ګران دی هغه جای کې چې جلال د ستا اوسیزی په ما ګران دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47472, 'Psalms 26:9', 'Psalms', 26, 9, 'ګناهکارو سره مه تباه کوه ما د قاتلو له تقدیره ته ساته ما', 'ګناهکارو سره مه تباه کوه ما د قاتلو له تقدیره ته ساته ما', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47473, 'Psalms 26:10', 'Psalms', 26, 10, 'هغه خلک چې جوړوي پلانونه تل د بدۍ چې همېش دې ته تیار وي رشوت واخلي', 'هغه خلک چې جوروی پلانونه تل د بدی چې همېش دې ته تیار وی رشوت واخلی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47474, 'Psalms 26:11', 'Psalms', 26, 11, 'خو زه کړم سم کارونه رحم وکړه ته په ما او نجات راکړه', 'خو زه کرم سم کارونه رحم وکره ته په ما او نجات راکره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47475, 'Psalms 26:12', 'Psalms', 26, 12, 'زه د ټولو خطرونو نه خوندي یم په لویه غونډه کې ثنا او صفت به د څښتن کومه', 'زه د تولو خطرونو نه خوندی یم په لویه غونده کې ثنا او صفت به د چشتن کومه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_26_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47476, 'Isaiah 24:1', 'Isaiah', 24, 1, 'ګورئ، نژدې دی چې څښتن ځمکه ورانه او ویجاړه او شاړه کړي. هغه به د ځمکې مخ کندې کپرې او خلک به یې خواره واره کړي.', 'ګوری، نژدې دی چې چشتن جمکه ورانه او ویجاره او شاره کری. هغه به د جمکې مخ کندې کپرې او خلک به یې خواره واره کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_001.mp3', 'https://drive.google.com/uc?id=1fQCvH-XaD4QHANTo9blfRWq10ThhJGp4&export=download', 1761237844, 1761237844),
(47477, 'Isaiah 24:2', 'Isaiah', 24, 2, 'که هغه عادي خلک وي یا کاهنان، غلامان وي یا باداران، وینځې وي یا بادارانې، اخیستونکي یا خرڅوونکي، پور ورکوونکي یا پور اخیستونکي، د دې ټولو تقدیر او قسمت به یوشان وي.', 'که هغه عادی خلک وی یا کاهنان، غلامان وی یا باداران، وینجې وی یا بادارانې، اخیستونکی یا خرچوونکی، پور ورکوونکی یا پور اخیستونکی، د دې تولو تقدیر او قسمت به یوشان وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_002.mp3', 'https://drive.google.com/file/d/1d3A4jfLzJW8-SILEmBm3evKeQITW57GW/preview', 1761237844, 1761237844),
(47478, 'Isaiah 24:3', 'Isaiah', 24, 3, 'ځمکه به په پوره توګه ویجاړه او لوټ شي. دا څښتن ویلي دي.', 'جمکه به په پوره توګه ویجاره او لوت شی. دا چشتن ویلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_003.mp3', 'https://drive.google.com/file/d/1dw7-suY9CrSrXmP9s4bXsu8UqBrPHg9S/preview', 1761237844, 1761237844),
(47479, 'Isaiah 24:4', 'Isaiah', 24, 4, 'ځمکه وچیږي، هرڅه مړاوي کیږي او د نړۍ بنیاد سستیږي. د نړۍ غوره خلک کمزوري کیږي.', 'جمکه وچیزی، هرچه مراوی کیزی او د نری بنیاد سستیزی. د نری غوره خلک کمزوری کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_004.mp3', 'https://drive.google.com/uc?id=1vjT5bpNjpqY7fefyWY_NERR7y3sWaiMJ&export=download', 1761237844, 1761237844),
(47480, 'Isaiah 24:5', 'Isaiah', 24, 5, 'خلکو د ځمکې مخ ناپاکه کړی دی، ځکه چې هغوی د څښتن د حکمونو څخه سرغړونه کړی ده او د هغه تلپاتې لوظ یې مات کړی دی.', 'خلکو د جمکې مخ ناپاکه کری دی، جکه چې هغوی د چشتن د حکمونو چخه سرغرونه کری ده او د هغه تلپاتې لوظ یې مات کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_005.mp3', 'https://drive.google.com/file/d/1lI4R4arfixLl0rPvPw7tK6D445kT1n_3/preview', 1761237844, 1761237844),
(47481, 'Isaiah 24:6', 'Isaiah', 24, 6, 'نو په دې خاطر ځمکه لعنتي شوې ده. خلک یې د خپلو کړنو سزا ویني او ورځ په ورځ د هغوی شمېر کمیږي.', 'نو په دې خاطر جمکه لعنتی شوې ده. خلک یې د خپلو کرنو سزا وینی او ورج په ورج د هغوی شمېر کمیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_006.mp3', 'https://drive.google.com/uc?id=1OwaCvP1Z8b2R-BamBtapjHE4AHjKVptO&export=download', 1761237844, 1761237844),
(47482, 'Isaiah 24:7', 'Isaiah', 24, 7, 'د انګورو تاکونه وچیږي او شراب کمیږي. کوم خلک چې یو وخت خوشحاله وو اوس اوسیلي وباسي.', 'د انګورو تاکونه وچیزی او شراب کمیزی. کوم خلک چې یو وخت خوشحاله وو اوس اوسیلی وباسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_007.mp3', 'https://drive.google.com/file/d/1LDT0cpX-o_6TZGv4lESQrzXT3fdW_V6D/preview', 1761237844, 1761237844),
(47483, 'Isaiah 24:8', 'Isaiah', 24, 8, 'د هغوی له خوشحالۍ ډک د چمبو او ربابونو اواز او د چړچو کوونکو اوازونه نور نه اورېدل کیږي.', 'د هغوی له خوشحالی دک د چمبو او ربابونو اواز او د چرچو کوونکو اوازونه نور نه اورېدل کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_008.mp3', 'https://drive.google.com/file/d/15STggc0gi7VL4xTFJ1SqY0HeFx9UoMKa/preview', 1761237844, 1761237844),
(47484, 'Isaiah 24:9', 'Isaiah', 24, 9, 'له بده مرغه خلک نور شراب نه څښي او سندرې نه وایي، هغوی ته شراب خوند نه ورکوي.', 'له بده مرغه خلک نور شراب نه چشی او سندرې نه وایی، هغوی ته شراب خوند نه ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_009.mp3', 'https://drive.google.com/uc?id=1TEEkTdupTfs3MicC_DzLfeqiNqxxvOgD&export=download', 1761237844, 1761237844),
(47485, 'Isaiah 24:10', 'Isaiah', 24, 10, 'ښار وران او ګډوډ شوی دی او د هر یو کور دروازه تړلې ده، ترڅو هېڅوک ورننه نه وځي.', 'شار وران او ګدود شوی دی او د هر یو کور دروازه ترلې ده، ترچو هېچوک ورننه نه وجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_010.mp3', 'https://drive.google.com/file/d/1v5C5MdQmU2zxlcpXWjCg0H8oigMqadkw/preview', 1761237844, 1761237844),
(47486, 'Isaiah 24:11', 'Isaiah', 24, 11, 'خلک په کوڅو کې د شرابو د نشتون له امله چیغې وهي. خوښي د تل دپاره له منځه تللې او خوشحالي د ځمکې له مخه ورکه شوې.', 'خلک په کوچو کې د شرابو د نشتون له امله چیغې وهی. خوشی د تل دپاره له منجه تللې او خوشحالی د جمکې له مخه ورکه شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_011.mp3', 'https://drive.google.com/file/d/19eiOYsKfJA7dmI0guKrfN3xgy7IeKj6R/preview', 1761237844, 1761237844),
(47487, 'Isaiah 24:12', 'Isaiah', 24, 12, 'ښار وران شوی او دروازې یې دړې وړې شوې دي.', 'شار وران شوی او دروازې یې درې ورې شوې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_012.mp3', 'https://drive.google.com/uc?id=1DcfDgkBCu7Zk19geYKaJ8TRZCyuuPgyh&export=download', 1761237844, 1761237844),
(47488, 'Isaiah 24:13', 'Isaiah', 24, 13, 'نو د نړۍ ټول قومونه به داسې شي لکه د زیتون د هغې ونې په شان چې مېوه یې راټوله او یا د هغه تاک په شان چې انګور یې شکول شوي وي.', 'نو د نری تول قومونه به داسې شی لکه د زیتون د هغې ونې په شان چې مېوه یې راتوله او یا د هغه تاک په شان چې انګور یې شکول شوی وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_013.mp3', 'https://drive.google.com/file/d/1M6rg3ss4jUDJbU8u-tK8K5CMYQEAfKMB/preview', 1761237844, 1761237844),
(47489, 'Isaiah 24:14', 'Isaiah', 24, 14, 'ژوندي پاتې شوي خلک د خوشحالۍ سندرې وایي. هغوی چې په لوېدیځ کې دي څښتن ته په لوړ اواز جلال ورکوي.', 'ژوندی پاتې شوی خلک د خوشحالی سندرې وایی. هغوی چې په لوېدیج کې دی چشتن ته په لور اواز جلال ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_014.mp3', 'https://drive.google.com/uc?id=1FRIkCTTjfnghXUHwnlqTro-woy6717vu&export=download', 1761237844, 1761237844),
(47490, 'Isaiah 24:15', 'Isaiah', 24, 15, 'څوک چې په ختیځ کې دي، د څښتن ستاینه وکړئ. څوک چې د بحیرې په غاړو او جزیرو کې دي، د اسراییلو د څښتن خدای ثنا او صفت وکړئ.', 'چوک چې په ختیج کې دی، د چشتن ستاینه وکری. چوک چې د بحیرې په غارو او جزیرو کې دی، د اسراییلو د چشتن خدای ثنا او صفت وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_015.mp3', 'https://drive.google.com/file/d/1QBzEsxZBGACOBAvEL0I4Z1dtxpZ5tQ9G/preview', 1761237844, 1761237844),
(47491, 'Isaiah 24:16', 'Isaiah', 24, 16, 'مونږ د نړۍ له هرې خوا د عادل خدای د ثنا او صفت سندرې اورو. خو افسوس زما په حال! زه د خاینانو د خیانت د دوام له امله ډنګر او کمزوری شوی یم. د هغوی ټګي نوره هم زیاتیږي.', 'مونز د نری له هرې خوا د عادل خدای د ثنا او صفت سندرې اورو. خو افسوس زما په حال! زه د خاینانو د خیانت د دوام له امله دنګر او کمزوری شوی یم. د هغوی تګی نوره هم زیاتیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_016.mp3', 'https://drive.google.com/uc?id=15qFtltFsfBMElNNmFrTyaAuxdxXs3fSh&export=download', 1761237844, 1761237844),
(47492, 'Isaiah 24:17', 'Isaiah', 24, 17, 'ای د نړۍ خلکو واورئ! وېره، کندې او دامونه تاسو ته تیار دي.', 'ای د نری خلکو واوری! وېره، کندې او دامونه تاسو ته تیار دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_017.mp3', 'https://drive.google.com/uc?id=15Op7ur1WF0DC5HRlMngLvbcZsin8uxjz&export=download', 1761237844, 1761237844),
(47493, 'Isaiah 24:18', 'Isaiah', 24, 18, 'که څوک له وېرې تښتي هغه به په کنده کې لویږي، که څوک له کندې ووځي هغه به په دام کې راګېر شي. سخت بارانونه وریږي او د ځمکې بنیادونه لړزیږي.', 'که چوک له وېرې تشتی هغه به په کنده کې لویزی، که چوک له کندې ووجی هغه به په دام کې راګېر شی. سخت بارانونه وریزی او د جمکې بنیادونه لرزیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_018.mp3', 'https://drive.google.com/uc?id=1xYSNbcJj_ysR_QZmAd3BK02RigQ7nXZu&export=download', 1761237844, 1761237844),
(47494, 'Isaiah 24:19', 'Isaiah', 24, 19, 'ځمکه به بیخي وچوي، هغه به سره بېله شي او سخته به ولړزیږي.', 'جمکه به بیخی وچوی، هغه به سره بېله شی او سخته به ولرزیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_019.mp3', 'https://drive.google.com/file/d/1BxpX5S4Wk6rFTM4sDRFVVBO49Fov0mHz/preview', 1761237844, 1761237844),
(47495, 'Isaiah 24:20', 'Isaiah', 24, 20, 'ځمکه به لکه د نشه سړي په شان کږه وږه لاړه شي او هغه به د یوې جونګړې په شان وي چې په توفان کې زنګیږي. نړۍ به د خپلو ګناهونو له امله کړوپه شي، هغه به داسې راوغورځیږي چې بیا به هېڅکله راپورته نه شي.', 'جمکه به لکه د نشه سری په شان کزه وزه لاره شی او هغه به د یوې جونګرې په شان وی چې په توفان کې زنګیزی. نری به د خپلو ګناهونو له امله کروپه شی، هغه به داسې راوغورجیزی چې بیا به هېچکله راپورته نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_020.mp3', 'https://drive.google.com/file/d/17skSBYImEMVDYbAqadyrNs1swq7rARa5/preview', 1761237844, 1761237844),
(47496, 'Isaiah 24:21', 'Isaiah', 24, 21, 'په هغه ورځ به څښتن په اسمان کې اسماني قدرتونو ته او په ځمکه کې د نړۍ پاچاهانو ته سزا ورکړي.', 'په هغه ورج به چشتن په اسمان کې اسمانی قدرتونو ته او په جمکه کې د نری پاچاهانو ته سزا ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_021.mp3', 'https://drive.google.com/uc?id=12NBU90mA6xoGn-K0k1dPOTvq7HPeavfQ&export=download', 1761237844, 1761237844),
(47497, 'Isaiah 24:22', 'Isaiah', 24, 22, 'خدای به هغوی د بندیانو په توګه په یوه کنده کې راغونډ کړي او له ډېرو ورځو وروسته به ورته سزا ورکړي.', 'خدای به هغوی د بندیانو په توګه په یوه کنده کې راغوند کری او له دېرو ورجو وروسته به ورته سزا ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_022.mp3', 'https://drive.google.com/file/d/1mVOyOIdkERJnyXY5bUUckIKOeJZo5hmr/preview', 1761237844, 1761237844),
(47498, 'Isaiah 24:23', 'Isaiah', 24, 23, 'نو سپوږمۍ به تیاره شي او لمر به نور نه ځلیږي، ځکه چې مطلق قادر څښتن به په اورشلیم کې د صهیون په غره باندې پاچاهي کوي او مشران به د هغه جلال ویني.', 'نو سپوزمی به تیاره شی او لمر به نور نه جلیزی، جکه چې مطلق قادر چشتن به په اورشلیم کې د صهیون په غره باندې پاچاهی کوی او مشران به د هغه جلال وینی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah024_verse_023.mp3', 'https://drive.google.com/uc?id=17f0VL0O_G158nstZd73BHB_Co87hjnoX&export=download', 1761237844, 1761237844),
(47499, 'Songofsongs 7:1', 'Songofsongs', 7, 1, 'ستا پښې په څپلو کښې څومره ښُکلې ښکارينه، اے د شهزادګۍ لورې. ستا غونډى پتونونه د قيمتى کاڼو په شان دينه، لکه چې دا يو ماهر زرګر جوړ کړى وينه.', 'ستا پشې په چپلو کشې چومره شکلې شکارینه، اے د شهزادګی لورې. ستا غوندی پتونونه د قیمتی کانو په شان دینه، لکه چې دا یو ماهر زرګر جور کری وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47500, 'Songofsongs 7:2', 'Songofsongs', 7, 2, 'ستا نوم د يوې پيالۍ په شان دېنه لکه چې د خوشبوداره ميو نه ډکه وينه. ستا پښې لکه د غنمو د ګېډۍ په شان دينه چې ګېرچاپېره ترې نه د لاله ګلونه راتاو شوى وينه.', 'ستا نوم د یوې پیالی په شان دېنه لکه چې د خوشبوداره میو نه دکه وینه. ستا پشې لکه د غنمو د ګېدی په شان دینه چې ګېرچاپېره ترې نه د لاله ګلونه راتاو شوی وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47501, 'Songofsongs 7:3', 'Songofsongs', 7, 3, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه،', 'ستا سینې لکه د هوسو د جوره بچو په شان دینه،', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47502, 'Songofsongs 7:4', 'Songofsongs', 7, 4, 'ستا غړۍ لکه د هاتى د غاښونو نه جوړه شوې مينارې په شان ښائسته ده نه. ستا سترګې د حسبون ښار د ځلېدونکو تالابونو په شان دينه، کوم تالابونه چې د دې ښار د بيت‌رابيم دروازې سره دينه. ستا پوزه د لبنان د برج په شان ښائسته ده نه چې د دمشق ښار ترې نه ښکارينه.', 'ستا غری لکه د هاتی د غاشونو نه جوره شوې مینارې په شان شایسته ده نه. ستا سترګې د حسبون شار د جلېدونکو تالابونو په شان دینه، کوم تالابونه چې د دې شار د بیت‌رابیم دروازې سره دینه. ستا پوزه د لبنان د برج په شان شایسته ده نه چې د دمشق شار ترې نه شکارینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47503, 'Songofsongs 7:5', 'Songofsongs', 7, 5, 'ستا سر لکه د کرمل د غرۀ په شان اوچت دېنه، ستا د زلفو ښائست لکه د شاهى ګُلکارۍ په شان دېنه تر دې چې بادشاهان هم ستا د کمڅو د ولونو بنديوان دينه.', 'ستا سر لکه د کرمل د غرۀ په شان اوچت دېنه، ستا د زلفو شایست لکه د شاهی ګلکاری په شان دېنه تر دې چې بادشاهان هم ستا د کمچو د ولونو بندیوان دینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47504, 'Songofsongs 7:6', 'Songofsongs', 7, 6, 'اے محبوبې، تۀ څومره ښُکلې او حسينه ينه، تۀ څومره د خوشحالو نه ډکه ينه.', 'اے محبوبې، تۀ چومره شکلې او حسینه ینه، تۀ چومره د خوشحالو نه دکه ینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47505, 'Songofsongs 7:7', 'Songofsongs', 7, 7, 'ستا قد او قامت د کجورې د ونې په شان دېنه، او ستا سينې د مېوو د غونچو په شان دينه.', 'ستا قد او قامت د کجورې د ونې په شان دېنه، او ستا سینې د مېوو د غونچو په شان دینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47506, 'Songofsongs 7:8', 'Songofsongs', 7, 8, 'ما وئيل زۀ به د کجورې ونې ته وخېژمه او کجورو ته به يې لاس وروړمه. ستا سينې دې د مېوو د غونچو په شان وينه، او ستا د خولې خوشبو دې لکه د سيوانو په شان وينه.', 'ما وییل زۀ به د کجورې ونې ته وخېژمه او کجورو ته به یې لاس ورورمه. ستا سینې دې د مېوو د غونچو په شان وینه، او ستا د خولې خوشبو دې لکه د سیوانو په شان وینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47507, 'Songofsongs 7:9', 'Songofsongs', 7, 9, 'او ستا شونډې د اعلىٰ ميو په شان دينه. نو دا مے دې زما د جانان په غاښونو او شونډو باندې په نرمۍ سره وبهيږينه. محبوبه', 'او ستا شوندې د اعلی میو په شان دینه. نو دا مے دې زما د جانان په غاشونو او شوندو باندې په نرمی سره وبهیزینه. محبوبه', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47508, 'Songofsongs 7:10', 'Songofsongs', 7, 10, 'زۀ د خپل جانان يمه، او د هغۀ زړۀ ما غواړينه.', 'زۀ د خپل جانان یمه، او د هغۀ زرۀ ما غوارینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47509, 'Songofsongs 7:11', 'Songofsongs', 7, 11, 'زما جانانه راشه، راځه چې بهر پټو ته لاړ شُو نه او هلته په کلى کښې شپه تېره کړو نه.', 'زما جانانه راشه، راجه چې بهر پتو ته لار شو نه او هلته په کلی کشې شپه تېره کرو نه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47510, 'Songofsongs 7:12', 'Songofsongs', 7, 12, 'راځه چې سحر وختى پاڅيږونه او د انګورو باغونو ته لاړ شونه چې د انګورو د ځيلو راټوکېدل ووينو او چې انارو ګلونه کړى دى کۀ نه، هلته به زۀ خپله مينه تا ته وښايمه.', 'راجه چې سحر وختی پاچیزونه او د انګورو باغونو ته لار شونه چې د انګورو د جیلو راتوکېدل ووینو او چې انارو ګلونه کری دی کۀ نه، هلته به زۀ خپله مینه تا ته وشایمه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47511, 'Songofsongs 7:13', 'Songofsongs', 7, 13, 'هلته به د مړه غونو بوټو خپله خوشبو راپرېښې وينه، او د ټولو نه ښې مېوې به زمونږ دروازې سره وينه، نوې او زاړۀ خوندونه، جانانه کوم چې ما ستا دپاره ساتلى دينه.', 'هلته به د مره غونو بوتو خپله خوشبو راپرېشې وینه، او د تولو نه شې مېوې به زمونز دروازې سره وینه، نوې او زارۀ خوندونه، جانانه کوم چې ما ستا دپاره ساتلی دینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47512, 'Job 41:1', 'Job', 41, 1, 'سمندرى بلاګانې تۀ د کُنډې سره راويستلے شې، يا د دې ژبه د پړى سره تړلے شې څۀ؟', 'سمندری بلاګانې تۀ د کندې سره راویستلے شې، یا د دې ژبه د پری سره ترلے شې چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47513, 'Job 41:2', 'Job', 41, 2, 'ولې تۀ دې ته پېزوان اچولے شې، يا يې په ژامنه کښې کُنډه اچولے شې؟', 'ولې تۀ دې ته پېزوان اچولے شې، یا یې په ژامنه کشې کنده اچولے شې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47514, 'Job 41:3', 'Job', 41, 3, 'ولې دا به د رحم دپاره تا ته ډېر مِنتُونه وکړى؟ يا به نرمې خبرې درته وکړى؟', 'ولې دا به د رحم دپاره تا ته دېر منتونه وکری؟ یا به نرمې خبرې درته وکری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47515, 'Job 41:4', 'Job', 41, 4, 'دا به تا سره يو لوظ وکړى څۀ چې ټول عُمر به ستا غلام وى؟', 'دا به تا سره یو لوظ وکری چۀ چې تول عمر به ستا غلام وی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47516, 'Job 41:5', 'Job', 41, 5, 'ولې تۀ به دا د يو مارغۀ په شان وساتې څۀ، يا تۀ به دا وتړې څۀ دپاره د دې چې ستا وينځې ورسره لوبې وکړى؟', 'ولې تۀ به دا د یو مارغۀ په شان وساتې چۀ، یا تۀ به دا وترې چۀ دپاره د دې چې ستا وینجې ورسره لوبې وکری؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
