(47518, 'Job 41:7', 'Job', 41, 7, 'ولې د هغې په څرمن باندې غشى څۀ اثر کوى، او د دې سر د نېزو سره غوڅولے شې؟', 'ولې د هغې په چرمن باندې غشی چۀ اثر کوی، او د دې سر د نېزو سره غوچولے شې؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47519, 'Job 41:8', 'Job', 41, 8, 'کۀ تۀ خپل لاس د دې سره ولګوې، نو د جنګ په مزه به پوهه شې، او بيا به هيڅکله داسې نۀ کوې.', 'کۀ تۀ خپل لاس د دې سره ولګوې، نو د جنګ په مزه به پوهه شې، او بیا به هیچکله داسې نۀ کوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47520, 'Job 41:9', 'Job', 41, 9, 'نه، د دې نيول څۀ فائده نۀ کوى، او کوم ښکارى چې د دې د نيولو کوشش کوى نو هغه به راوغورزولے شى.', 'نه، د دې نیول چۀ فایده نۀ کوی، او کوم شکاری چې د دې د نیولو کوشش کوی نو هغه به راوغورزولے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47521, 'Job 41:10', 'Job', 41, 10, 'هيڅ څوک هم دا جرأت نۀ شى کولے چې کار ورسره وساتى. او د دې په وړاندې څوک ټېنګېدے شى؟', 'هیچ چوک هم دا جرات نۀ شی کولے چې کار ورسره وساتی. او د دې په وراندې چوک تېنګېدے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47522, 'Job 41:11', 'Job', 41, 11, 'چا ما له څۀ راکړى دى چې زۀ بدله ورکړم؟ د آسمان نه لاندې هر څۀ زما دى؟', 'چا ما له چۀ راکری دی چې زۀ بدله ورکرم؟ د اسمان نه لاندې هر چۀ زما دی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47523, 'Job 41:12', 'Job', 41, 12, 'زۀ به د دې د بدن د اندامونو په حقله خاموشى نۀ اختياروم، يا د دې د لوئ طاقت او د دې د ښۀ بدن په حقله به وايم.', 'زۀ به د دې د بدن د اندامونو په حقله خاموشی نۀ اختیاروم، یا د دې د لوی طاقت او د دې د شۀ بدن په حقله به وایم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47524, 'Job 41:13', 'Job', 41, 13, 'د دې نه څرمن څوک ويستے شى؟ د دې ډکه څرمن څوک سورے کولے شى؟', 'د دې نه چرمن چوک ویستے شی؟ د دې دکه چرمن چوک سورے کولے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47525, 'Job 41:14', 'Job', 41, 14, 'د دې د خولې ژامنې څوک کولاولے شى؟ ځکه چې د دې غاښونه خلق يروى.', 'د دې د خولې ژامنې چوک کولاولے شی؟ جکه چې د دې غاشونه خلق یروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47526, 'Job 41:15', 'Job', 41, 15, 'د دې ملا د ډالونو قطارونو نه جوړه ده، دا د يو بل سره کلک انښلى.', 'د دې ملا د دالونو قطارونو نه جوره ده، دا د یو بل سره کلک انشلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47527, 'Job 41:16', 'Job', 41, 16, 'د يو بل سره دومره نزدې دى، چې د دې په مينځ کښې هوا هم نۀ شى تېرېدلے.', 'د یو بل سره دومره نزدې دی، چې د دې په مینج کشې هوا هم نۀ شی تېرېدلے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47528, 'Job 41:17', 'Job', 41, 17, 'دا د يو بل سره تړلى شوى دى، دې يو بل نيولے دے او د يو بل نه نۀ جدا کيږى.', 'دا د یو بل سره ترلی شوی دی، دې یو بل نیولے دے او د یو بل نه نۀ جدا کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47529, 'Job 41:18', 'Job', 41, 18, 'د دې انټوشى لکه د رڼا پړق وى، او د دې سترګې د سحر د سوروالى په شان دى.', 'د دې انتوشی لکه د رنا پرق وی، او د دې سترګې د سحر د سوروالی په شان دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47530, 'Job 41:19', 'Job', 41, 19, 'د دې خولې نه د ډيوو شُغلې ځى، او د اور ذرې ترې نه راوځى.', 'د دې خولې نه د دیوو شغلې جی، او د اور ذرې ترې نه راوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47531, 'Job 41:20', 'Job', 41, 20, 'د دې د پوزې نه لوګے راوځى، لکه چې د پتيلې لاندې د بلو لوخو لوګے وى.', 'د دې د پوزې نه لوګے راوجی، لکه چې د پتیلې لاندې د بلو لوخو لوګے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47532, 'Job 41:21', 'Job', 41, 21, 'د دې ساه سکارۀ بلوى، او د دې خولې نه يوه لمبه راوځى.', 'د دې ساه سکارۀ بلوی، او د دې خولې نه یوه لمبه راوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47533, 'Job 41:22', 'Job', 41, 22, 'د دې څټ مضبوط دے، او چې چرته هم ځى نو هلته يره راځى.', 'د دې چت مضبوط دے، او چې چرته هم جی نو هلته یره راجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47534, 'Job 41:23', 'Job', 41, 23, 'د دې د غوښې موړې د يوې بلې سره انښتې دى، دا مضبوطې جوړې دى او نۀ خوځيږى.', 'د دې د غوشې مورې د یوې بلې سره انشتې دی، دا مضبوطې جورې دی او نۀ خوجیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47535, 'Job 41:24', 'Job', 41, 24, 'د دې زړۀ د کاڼى په شان سخت دے، لکه د ژرندې د کاڼى په شان سخت دے.', 'د دې زرۀ د کانی په شان سخت دے، لکه د ژرندې د کانی په شان سخت دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47536, 'Job 41:25', 'Job', 41, 25, 'کله چې دا په خپله پاڅى نو طاقتور خلق ويريږى، او يرې نه وتښتى.', 'کله چې دا په خپله پاچی نو طاقتور خلق ویریزی، او یرې نه وتشتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47537, 'Job 41:26', 'Job', 41, 26, 'داسې تُوره نشته چې زخمى يې کړى، نۀ پرې نېزه، نۀ غشے او نۀ ورباندې نرۍ نېزه څۀ اثر کوى.', 'داسې توره نشته چې زخمی یې کری، نۀ پرې نېزه، نۀ غشے او نۀ ورباندې نری نېزه چۀ اثر کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47538, 'Job 41:27', 'Job', 41, 27, 'دا اوسپنه د بوسو په شان ګڼى، او زېړ د ورَستو شوو لرګو په شان ګڼى.', 'دا اوسپنه د بوسو په شان ګنی، او زېر د ورستو شوو لرګو په شان ګنی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47539, 'Job 41:28', 'Job', 41, 28, 'غشى دا نۀ شى شړلے، او د ليندې کاڼى خو ورته ګپ ښکارى.', 'غشی دا نۀ شی شرلے، او د لیندې کانی خو ورته ګپ شکاری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_28.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47540, 'Job 41:29', 'Job', 41, 29, 'لَوړ د بوسو په شان ګڼى، او د نرو نېزو په راويستلو پورې دا خندا کوى.', 'لور د بوسو په شان ګنی، او د نرو نېزو په راویستلو پورې دا خندا کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47541, 'Job 41:30', 'Job', 41, 30, 'د دې خېټه د تېرو ماتو شوو شيشو په شان ده، دا په خټه باندې داسې نښه پرېږدى لکه چې په مېخونو سورے شوے وى.', 'د دې خېته د تېرو ماتو شوو شیشو په شان ده، دا په خته باندې داسې نشه پرېزدی لکه چې په مېخونو سورے شوے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47542, 'Job 41:31', 'Job', 41, 31, 'دا سمندر د يشېدلو اوبو په شان خوځوى، او دا سمندر داسې شاربى لکه شُملې.', 'دا سمندر د یشېدلو اوبو په شان خوجوی، او دا سمندر داسې شاربی لکه شملې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_31.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47543, 'Job 41:32', 'Job', 41, 32, 'دا د خپل ځان شا ته يو پړقېدونکې کرښه پرېږدى، او سمندر تک سپين کړى', 'دا د خپل جان شا ته یو پرقېدونکې کرشه پرېزدی، او سمندر تک سپین کری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47544, 'Job 41:33', 'Job', 41, 33, 'په زمکه باندې د دې ثانى نشته، دا يو داسې مخلوق دے چې نۀ يريږى.', 'په زمکه باندې د دې ثانی نشته، دا یو داسې مخلوق دے چې نۀ یریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_33.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47545, 'Job 41:34', 'Job', 41, 34, 'دا په ټولو کښې ډېر مغرور دے، دا د ټولو ځناورو بادشاه دے.“', 'دا په تولو کشې دېر مغرور دے، دا د تولو جناورو بادشاه دے.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_41_34.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47546, 'Jonah 3:1', 'Jonah', 3, 1, 'بیا په دوهم ځل څښتن یونس ته وویل:', 'بیا په دوهم جل چشتن یونس ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/jonah003_verse_001.mp3', 'https://drive.google.com/file/d/1E6RX3MzXe2CAgd-UzYLIMyCP3l7hnRMJ/preview', 1761237844, 1761237844),
(47547, 'Jonah 3:2', 'Jonah', 3, 2, '«همدا اوس د نینوا لوی ښار ته لاړ شه او هغه پیغام خلکو ته اعلان کړه چې زه یې تاته درکوم.»', '«همدا اوس د نینوا لوی شار ته لار شه او هغه پیغام خلکو ته اعلان کره چې زه یې تاته درکوم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/jonah003_verse_002.mp3', 'https://drive.google.com/uc?id=1xG760UIIDU_wtkQ200HPi39mxoPDaYVt&export=download', 1761237844, 1761237844),
(47548, 'Jonah 3:3', 'Jonah', 3, 3, 'نو یونس د څښتن خبره ومنله او نینوا ته لاړ. نینوا یو ډېر لوی ښار ؤ چې په ګرځېدلو کې یې درې ورځې لګېدلې.', 'نو یونس د چشتن خبره ومنله او نینوا ته لار. نینوا یو دېر لوی شار و چې په ګرجېدلو کې یې درې ورجې لګېدلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/jonah003_verse_003.mp3', 'https://drive.google.com/uc?id=1L8WrYuHRfWBvDbne8VbYapcf9bByteYI&export=download', 1761237844, 1761237844),
